def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    # find connected components (4-conn) of non-bg
    seen=[[False]*W for _ in range(H)]; comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==g[a][b]:
                            seen[x][y]=True; st.append((x,y))
                comps.append(comp)
    res=[row[:] for row in g]
    for comp in comps:
        rows=[r for r,c in comp]; maxc=max(c for r,c in comp)
        bot=max(rows)
        for r,c in comp:
            nr=r
            if r==bot or c==maxc: continue
            res[r][c+1]=res[r][c]
            res[r][c]=bg
    return res
