    H,W=len(g),len(g[0]); o=[[bg_]*W for _ in range(H)]
    for r in range(H):
        for c in range(W-1,-1,-1):
            v=g[r][c]
            if v!=bg_ and c+1<W and o[r][c+1]==bg_:
                o[r][c+1]=v
    return o
