def sim(order_key):
    H,W=len(g),len(g[0]); vals=[x for r in g for x in r]; bg=collections.Counter(vals).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)];seen[r][c]=True;cc=[]
                while st:
                    a,b=st.pop();cc.append((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==g[a][b]:
                            seen[x][y]=True;st.append((x,y))
                res.append(cc)
