# Per-cell classification across all 7 demos: S = keeps color at same spot in Out AND its right neighbor cell in Out is different color or bg... Use strict assignment: match each input cell to exactly one same-color output cell via bipartite matching minimizing movement cost, then classify.
def analyze(n):
    In=G[f'Demo pair {n} input']; Out=G[f'Demo pair {n} output']
    H,W=len(In),len(In[0]); vals=[x for r in In for x in r]; bg=collections.Counter(vals).most_common(1)[0][0]
    # greedy: repeatedly place each nonbg output cell back to nearest input cell of same color (assign each input cell at most once)
    rem=set((r,c) for r in range(H) for c in range(W) if In[r][c]!=bg)
    assign={}
    for r in range(H):
        for c in range(W):
            if Out[r][c]==bg: continue
            v=Out[r][c]
            best=None
            for p in list(rem):
                if In[p[0]][p[1]]==v:
                    sc=(abs(p[0]-r)+abs(p[1]-c), max(abs(p[0]-r),abs(p[1]-c)))
                    if best is None or sc<best: best=p
            if best: rem.discard(best); assign[(r,c)]=best
    stats=collections.Counter()
    for (r,c),(rr,cc2) in assign.items():
        stats[(rr-r, cc2-c)*((-1,) or ()) if False else (rr-r,cc2-c)]+=1
    print('pair',n,'assign stats:',dict(stats),'unassigned_in=',len(rem),'unmatched_out=',sum(1 for r in range(H) for c in range(W) if Out[r][c]!=bg and (r,c) not in assign.values()))
for n in [1,2,3,4,5,6,7]: analyze(n)

